    elif item_type == cJSON_Raw:
        if item.valuestring is None:
            return False

        # In Python, valuestring could be str or bytes
        valuestring = item.valuestring
        if isinstance(valuestring, str):
            valuestring_bytes = valuestring.encode("utf-8") + b"\x00"
        else:
            valuestring_bytes = valuestring + b"\x00"

        raw_length = len(valuestring_bytes)
        output = ensure(output_buffer, raw_length)
        if output is None:
            return False

        output[:raw_length] = valuestring_bytes
        return True

    elif item_type == cJSON_String:
        return print_string(item, output_buffer)

    elif item_type == cJSON_Array:
        return print_array(item, output_buffer)

    elif item_type == cJSON_Object:
        return print_object(item, output_buffer)

